phase = 'waypoint'
for step in range(60):
    pose = get_pose()
    if phase == 'waypoint':
        target_x = get_waypoint()['x']
        target_y = get_waypoint()['y']
    else:
        target_x = get_goal()['x']
        target_y = get_goal()['y']

    target_heading = heading_to(target_x, target_y)
    err = target_heading - pose['heading_deg']
    err = (err + 180) % 360 - 180  # normalise to [-180, 180]

    wz = err * 0.8 / 180.0
    if wz > 0.8:
        wz = 0.8
    if wz < -0.8:
        wz = -0.8

    if phase == 'waypoint':
        d = distance_to(target_x, target_y)
        if d > 0.6:
            vx = 0.5 if abs(err) <= 90 else 0.3
        else:
            vx = 0.2
    else:
        d = distance_to(target_x, target_y)
        if d > 0.5:
            vx = 0.3 if abs(err) <= 90 else 0.2
        else:
            vx = 0.0

    vy = 0.0
    result = walk(vx, vy, wz, 1)

    if result.get('fell', False):
        log("Fell down!")
        break

    if phase == 'waypoint' and result.get('dist_way_m', 100) <= 0.6:
        phase = 'goal'
        log("Waypoint passed")

    if phase == 'goal' and result.get('dist_goal_m', 100) <= 0.5:
        log("Goal reached, stopping")
        stop(1)
        break
